-- CR-R17 forward source. SQL UNPARSED/UNEXECUTED; physical cleanup unverified.
-- Bounded ENROLLMENT/DELIVERY, no total-version cap or lease/exclusivity claim.
begin;
set local statement_timeout='10s';
set local lock_timeout='1s';
set local idle_in_transaction_session_timeout='15s';
set local search_path='';

create function private.r17_storage_key(p_org uuid,p_root uuid,p_version uuid) returns text
language sql immutable set search_path='' as $r17_key$
 select 'organizations/'||p_org::text||'/resumes/'||p_root::text||'/versions/'||p_version::text||'.pdf';
$r17_key$;

create function private.r17_version_write_guard() returns trigger
language plpgsql volatile security definer set search_path='' as $r17_version_guard$
begin
 if tg_op='UPDATE' and (to_jsonb(new)-array['page_count','updated_at']) is distinct from (to_jsonb(old)-array['page_count','updated_at'])
  then raise exception 'RETENTION_VERSION_IDENTITY' using errcode='23514';end if;
 if not private.try_candidate_privacy_write(new.owner_id) then raise exception 'CANDIDATE_WRITE_BLOCKED' using errcode='42501';end if;
 -- SHARE conflicts with the non-key root status UPDATE; KEY SHARE would not.
 perform 1 from public.resumes r where r.id=new.resume_id and r.owner_id=new.owner_id and r.organization_id=new.organization_id and r.status='active'
  for share skip locked;
 if not found then raise exception 'RETENTION_SOURCE_INACTIVE_OR_BUSY' using errcode='55P03';end if;
 if new.storage_key is distinct from private.r17_storage_key(new.organization_id,new.resume_id,new.id)
  then raise exception 'RETENTION_STORAGE_IDENTITY' using errcode='23514';end if;
 return new;
end;
$r17_version_guard$;
create trigger zy_retention_version_write before insert or update on public.resume_versions for each row execute function private.r17_version_write_guard();

create function private.r17_root_tombstone_guard() returns trigger
language plpgsql volatile set search_path='' as $r17_tombstone$
begin
 if old.status='deleted' and new.status is distinct from 'deleted' then raise exception 'RETENTION_ROOT_TOMBSTONE' using errcode='23514';end if;
 return new;
end;
$r17_tombstone$;
create trigger zy_retention_root_tombstone before update on public.resumes for each row execute function private.r17_root_tombstone_guard();

create function private.r17_lock_root(p_owner uuid,p_root uuid) returns public.resumes
language plpgsql volatile set search_path='' as $r17_lock_root$
declare root_row public.resumes%rowtype;expected bigint;locked bigint;
begin
 if p_owner is null or p_root is null or current_setting('transaction_isolation') not in ('read committed','read uncommitted')
  then raise exception 'RETENTION_SOURCE_UNAVAILABLE' using errcode='23514';end if;
 -- Callers may have selected a root already: no reverse blocking owner wait.
 if not private.try_lock_candidate_owners(array[p_owner]) then raise exception 'PRIVACY_OWNER_BUSY' using errcode='55P03';end if;
 select * into root_row from public.resumes where id=p_root and owner_id=p_owner for update skip locked;
 if not found then raise exception 'RETENTION_PARENT_REPAIR_REQUIRED' using errcode='55P03';end if;
 if exists(select 1 from public.resume_versions v where v.resume_id=p_root and (v.owner_id<>p_owner or v.organization_id<>root_row.organization_id
   or v.storage_key is distinct from private.r17_storage_key(v.organization_id,v.resume_id,v.id)))
  then raise exception 'RETENTION_VERSION_REPAIR_REQUIRED' using errcode='23514';end if;
 select count(*) into expected from public.resume_versions where resume_id=p_root;
 select count(*) into locked from (select v.id from public.resume_versions v where v.resume_id=p_root for share skip locked) q;
 if locked<>expected then raise exception 'RETENTION_SOURCE_BUSY' using errcode='55P03';end if;
 if exists(select 1 from private.retention_items t where t.resume_id=p_root and (t.owner_id<>p_owner
   or not exists(select 1 from public.resume_versions v where v.resume_id=p_root and v.owner_id=p_owner
      and v.organization_id=root_row.organization_id and v.storage_key=t.storage_key)
   or not isfinite(t.created_at) or (t.completed_at is not null and t.status<>'deleted')))
  or exists(select 1 from public.resume_versions v join private.retention_items t on t.storage_key=v.storage_key
    where v.resume_id=p_root and (t.resume_id<>p_root or t.owner_id<>p_owner))
  then raise exception 'RETENTION_ITEM_REPAIR_REQUIRED' using errcode='23514';end if;
 return root_row;
end;
$r17_lock_root$;

create function private.r17_root_covered(p_owner uuid,p_root uuid,p_org uuid) returns boolean
language sql stable set search_path='' as $r17_covered$
 select exists(select 1 from public.resumes r where (r.id,r.owner_id,r.organization_id)=(p_root,p_owner,p_org) and r.status='deleted')
  and not exists(select 1 from public.resume_versions v where v.resume_id=p_root and (
   v.owner_id<>p_owner or v.organization_id<>p_org or v.storage_key is distinct from private.r17_storage_key(p_org,p_root,v.id)
   or not exists(select 1 from private.retention_items t where t.resume_id=p_root and t.owner_id=p_owner and t.storage_key=v.storage_key and t.status='deleted')))
  and not exists(select 1 from private.retention_items t where t.resume_id=p_root and (t.owner_id<>p_owner or t.status<>'deleted'
   or not exists(select 1 from public.resume_versions v where v.resume_id=p_root and v.owner_id=p_owner and v.organization_id=p_org and v.storage_key=t.storage_key)));
$r17_covered$;

-- Fixed terminal preimage/postimage composition only; never runtime SQL dispatch.
do $r17_forward$
declare item jsonb;p pg_catalog.pg_proc%rowtype;definition text;statements text[]:=array[]::text[];ddl text;
 manifest jsonb:=$r17_patches$[{"signature":"public.claim_expired_resume_objects(timestamp with time zone,integer)","before":"f1a6211babdb22f10b469f34b06c139af20765b3e21f243fd7b1aff77d110ea1","after":"f2fe440872b39be1647a1d5615bc9c581dce677c8823283c76a85bf95918513b","old":"\ndeclare candidate record;claimed private.retention_items%rowtype;\nbegin\n if p_limit is null or p_limit<1 or p_limit>1000 or p_before is null or not isfinite(p_before) then\n  raise exception 'invalid retention batch size' using errcode='22023';end if;\n for candidate in\n  select rv.resume_id,rv.owner_id,rv.storage_key from public.resume_versions rv join public.resumes r on r.id=rv.resume_id\n  where ((r.status='active' and r.created_at<p_before) or (r.status='deleted' and exists(\n    select 1 from private.retention_items t where t.resume_id=r.id and t.status='failed')))\n   and not exists(select 1 from private.retention_items t where t.storage_key=rv.storage_key and t.status='deleted')\n  order by r.created_at,rv.id limit p_limit for update of rv,r skip locked loop\n  -- Source rows may already be locked: owner acquisition must never wait.\n  if not private.try_lock_candidate_owners(array[candidate.owner_id]) then raise exception 'PRIVACY_OWNER_BUSY' using errcode='55P03';end if;\n  insert into private.retention_items as t(resume_id,owner_id,storage_key,status,attempt_count,created_at)\n   values(candidate.resume_id,candidate.owner_id,candidate.storage_key,'queued',1,clock_timestamp())\n   on conflict on constraint retention_items_storage_key_key do update\n    set status='queued',attempt_count=t.attempt_count+1,last_error_code=null returning * into claimed;\n  -- Separate commands observe the inserted item. First version claim captures ALL root versions/operations.\n  perform private.capture_owned_ai_operation_dispositions(candidate.owner_id,candidate.resume_id,null,claimed.id);\n  update public.resumes r set status='deleted',updated_at=timezone('utc',now()) where r.id=candidate.resume_id;\n  item_id:=claimed.id;resume_id:=claimed.resume_id;storage_key:=claimed.storage_key;return next;\n end loop;\nend;\n","new":"declare candidate public.resumes%rowtype;root_row public.resumes%rowtype;version_row public.resume_versions%rowtype;\n item_row private.retention_items%rowtype;delivered record;result_row jsonb;results jsonb:='[]'::jsonb;\n enroll_count integer:=0;return_count integer:=0;first_item uuid;first_at timestamptz;enrolled_at timestamptz;\nbegin\n if p_limit is null or p_limit<1 or p_limit>1000 or p_before is null or not isfinite(p_before)\n  then raise exception 'invalid retention batch size' using errcode='22023';end if;\n if private.owned_ai_disposition_ready() is not true then raise exception 'RETENTION_SOURCE_UNAVAILABLE' using errcode='23514';end if;\n -- The retained version rows are durable uncovered version inventory. p_limit\n -- bounds new keys and delivered work, NEVER the root's total history.\n select r.* into candidate from public.resumes r where ((r.status='active' and r.created_at<p_before) or r.status='deleted')\n  and (exists(select 1 from public.resume_versions v where v.resume_id=r.id and not exists(\n    select 1 from private.retention_items t where t.resume_id=r.id and t.owner_id=r.owner_id and t.storage_key=v.storage_key))\n   or exists(select 1 from private.retention_items t where t.resume_id=r.id and t.status<>'deleted'))\n  order by case when exists(select 1 from public.resume_versions v where v.resume_id=r.id and not exists(\n    select 1 from private.retention_items t where t.resume_id=r.id and t.owner_id=r.owner_id and t.storage_key=v.storage_key)) then 0\n   else coalesce((select min(t.attempt_count) from private.retention_items t where t.resume_id=r.id and t.status<>'deleted'),2147483647) end,\n   r.created_at,r.id limit 1 for update of r skip locked;\n if not found then return;end if;\n root_row:=private.r17_lock_root(candidate.owner_id,candidate.id);\n select min(t.created_at) into first_at from private.retention_items t where t.resume_id=root_row.id and t.owner_id=root_row.owner_id;\n if root_row.status='deleted' and first_at is null then raise exception 'RETENTION_FIRST_CLOCK_REPAIR_REQUIRED' using errcode='23514';end if;\n enrolled_at:=clock_timestamp();\n if first_at is not null and (not isfinite(first_at) or enrolled_at<=first_at)\n  then raise exception 'RETENTION_FIRST_CLOCK_REPAIR_REQUIRED' using errcode='23514';end if;\n for version_row in select v.* from public.resume_versions v where v.resume_id=root_row.id and not exists(\n   select 1 from private.retention_items t where t.resume_id=root_row.id and t.owner_id=root_row.owner_id and t.storage_key=v.storage_key)\n   order by v.created_at,v.id limit p_limit for update of v skip locked loop\n  exit when enroll_count>=p_limit;\n  insert into private.retention_items(resume_id,owner_id,storage_key,status,attempt_count,created_at)\n    values(root_row.id,root_row.owner_id,version_row.storage_key,'queued',0,enrolled_at)\n    on conflict on constraint retention_items_storage_key_key do nothing;\n  if found then enroll_count:=enroll_count+1;end if;\n  if not exists(select 1 from private.retention_items t where t.resume_id=root_row.id and t.owner_id=root_row.owner_id and t.storage_key=version_row.storage_key)\n    then raise exception 'RETENTION_ITEM_IDENTITY_CONFLICT' using errcode='23514';end if;\n end loop;\n for delivered in select t.* from private.retention_items t join public.resume_versions v on v.resume_id=t.resume_id and v.storage_key=t.storage_key\n  where t.resume_id=root_row.id and t.owner_id=root_row.owner_id and v.owner_id=root_row.owner_id and v.organization_id=root_row.organization_id\n   and t.status in ('queued','failed') order by t.attempt_count,t.created_at,t.id limit p_limit for update of t skip locked loop\n  exit when return_count>=p_limit;\n  update private.retention_items set status='queued',attempt_count=attempt_count+1,last_error_code=null\n    where id=delivered.id and status in ('queued','failed') returning * into item_row;\n  if not found then raise exception 'RETENTION_ITEM_BUSY' using errcode='55P03';end if;\n  if first_item is null then first_item:=item_row.id;end if;\n  results:=results||jsonb_build_array(jsonb_build_object('item_id',item_row.id,'resume_id',item_row.resume_id,'storage_key',item_row.storage_key));\n  return_count:=return_count+1;\n end loop;\n if return_count=0 then return;end if;\n -- Separate commands observe enrollment. Existing capture owns all operation\n -- states and preserves the earliest item/cause, including deleted old items.\n perform private.capture_owned_ai_operation_dispositions(root_row.owner_id,root_row.id,null,first_item);\n update public.resumes set status='deleted',updated_at=timezone('utc',now()) where id=root_row.id;\n for result_row in select value from jsonb_array_elements(results) loop\n  item_id:=(result_row->>'item_id')::uuid;resume_id:=(result_row->>'resume_id')::uuid;storage_key:=result_row->>'storage_key';return next;\n end loop;\nend;\n","setof":true},{"signature":"public.complete_retention_item(uuid)","before":"0307152ae26d0bbcc0239d932e15253849c159c615070b93270c2e8c9b5335be","after":"89fddcba7c5d3ee9f745e9f9afdff7aa7eeedce59237805f7864e495a49f4898","old":"\ndeclare\n  item_row private.retention_items%rowtype;\nbegin\n  update private.retention_items\n  set status = 'deleted', completed_at = timezone('utc', now()), last_error_code = null\n  where id = p_item_id\n  returning * into item_row;\n  if not found then return false; end if;\n\n  if exists(select 1 from public.resumes r where r.id=item_row.resume_id and r.owner_id=item_row.owner_id\n    and not exists(select 1 from private.retention_items ri where ri.resume_id=r.id and ri.status<>'deleted')) then\n    perform private.retire_initial_feedback_publications(item_row.owner_id,item_row.resume_id,null,item_row.id);\n  end if;\n  delete from public.resumes r\n  where r.id = item_row.resume_id and r.owner_id=item_row.owner_id and r.status='deleted'\n    and not exists (\n      select 1 from private.retention_items ri\n      where ri.resume_id = r.id and ri.status <> 'deleted'\n    );\n  return true;\nend;\n","new":"declare selected private.retention_items%rowtype;item_row private.retention_items%rowtype;root_row public.resumes%rowtype;\nbegin\n select * into selected from private.retention_items where id=p_item_id;\n if not found then return false;end if;\n if selected.status='deleted' then return true;end if;\n if private.owned_ai_disposition_ready() is not true then raise exception 'RETENTION_SOURCE_UNAVAILABLE' using errcode='23514';end if;\n if not private.try_lock_candidate_owners(array[selected.owner_id]) then raise exception 'PRIVACY_OWNER_BUSY' using errcode='55P03';end if;\n -- Re-read terminal state after owner acquisition BEFORE requiring a parent:\n -- another completion may have committed both deletion and parent cascade.\n select * into item_row from private.retention_items where id=p_item_id for update skip locked;\n if not found then\n  if exists(select 1 from private.retention_items where id=p_item_id) then raise exception 'RETENTION_ITEM_BUSY' using errcode='55P03';end if;\n  return false;\n end if;\n if (item_row.owner_id,item_row.resume_id,item_row.storage_key) is distinct from (selected.owner_id,selected.resume_id,selected.storage_key)\n  then raise exception 'RETENTION_ITEM_IDENTITY_CONFLICT' using errcode='23514';end if;\n if item_row.status='deleted' then return true;end if;\n root_row:=private.r17_lock_root(item_row.owner_id,item_row.resume_id);\n if root_row.status<>'deleted' or not exists(select 1 from public.resume_versions v where v.resume_id=root_row.id and v.owner_id=root_row.owner_id\n   and v.organization_id=root_row.organization_id and v.storage_key=item_row.storage_key\n   and v.storage_key=private.r17_storage_key(v.organization_id,v.resume_id,v.id))\n  then raise exception 'RETENTION_PARENT_REPAIR_REQUIRED' using errcode='23514';end if;\n update private.retention_items set status='deleted',completed_at=clock_timestamp(),last_error_code=null where id=p_item_id and status in ('queued','failed');\n if not found then raise exception 'RETENTION_ITEM_STATE' using errcode='23514';end if;\n -- Missing/unenrolled actual versions prevent BOTH publication retirement and\n -- parent cascade, even when every recorded work item is already deleted.\n if private.r17_root_covered(root_row.owner_id,root_row.id,root_row.organization_id) is true then\n  perform private.retire_initial_feedback_publications(root_row.owner_id,root_row.id,null,item_row.id);\n  -- Recheck coverage under the same owner/root/source locks immediately before DELETE.\n  delete from public.resumes r where r.id=root_row.id and r.owner_id=root_row.owner_id and r.status='deleted'\n    and private.r17_root_covered(root_row.owner_id,root_row.id,root_row.organization_id) is true;\n  if not found then raise exception 'RETENTION_COVERAGE_CHANGED' using errcode='23514';end if;\n end if;\n return true;\nend;\n","setof":false},{"signature":"public.fail_retention_item(uuid,text)","before":"6f19a96018773c990f15be509be1b207a1852622176c7d8a903848a25f9d3455","after":"217ddcad5c3345b81f24dbd35bf0d70ce155315ee40188540610c81343064b86","old":"\nbegin\n  if p_error_code is null or btrim(p_error_code) = '' then return false; end if;\n  update private.retention_items\n  set status = 'failed', last_error_code = p_error_code\n  where id = p_item_id;\n  return found;\nend;\n","new":"declare selected private.retention_items%rowtype;item_row private.retention_items%rowtype;root_row public.resumes%rowtype;\nbegin\n if p_error_code is null or btrim(p_error_code)='' then return false;end if;\n select * into selected from private.retention_items where id=p_item_id;\n if not found then return false;end if;\n if selected.status='deleted' then return false;end if;\n if private.owned_ai_disposition_ready() is not true then raise exception 'RETENTION_SOURCE_UNAVAILABLE' using errcode='23514';end if;\n if not private.try_lock_candidate_owners(array[selected.owner_id]) then raise exception 'PRIVACY_OWNER_BUSY' using errcode='55P03';end if;\n -- Re-read terminal state after owner acquisition BEFORE requiring a parent:\n -- another completion may have committed both deletion and parent cascade.\n select * into item_row from private.retention_items where id=p_item_id for update skip locked;\n if not found then\n  if exists(select 1 from private.retention_items where id=p_item_id) then raise exception 'RETENTION_ITEM_BUSY' using errcode='55P03';end if;\n  return false;\n end if;\n if item_row.status='deleted' then return false;end if;\n if (item_row.owner_id,item_row.resume_id,item_row.storage_key) is distinct from (selected.owner_id,selected.resume_id,selected.storage_key) then raise exception 'RETENTION_ITEM_IDENTITY_CONFLICT' using errcode='23514';end if;\n root_row:=private.r17_lock_root(item_row.owner_id,item_row.resume_id);\n if root_row.status<>'deleted' or not exists(select 1 from public.resume_versions v where v.resume_id=root_row.id and v.owner_id=root_row.owner_id\n    and v.organization_id=root_row.organization_id and v.storage_key=item_row.storage_key)\n  then raise exception 'RETENTION_ITEM_REPAIR_REQUIRED' using errcode='23514';end if;\n update private.retention_items set status='failed',last_error_code=p_error_code where id=p_item_id and status in ('queued','failed');\n return found;\nend;\n","setof":false},{"signature":"private.owned_ai_retirement_ready()","before":"d5330d9d5dae482c055bf2f61b08fcd838c603865732d4578e90440be9c79e46","after":"5beec572fc142c904c1dc7282d5da5fbae844818126089a07085da267ecc6aaf","old":"\ndeclare item jsonb;p pg_catalog.pg_proc%rowtype;owner_oid oid;service_oid oid;role_name text;rel pg_catalog.pg_class%rowtype;col jsonb;expected smallint[];\n manifest jsonb:=$retirement_catalog$[{\"signature\":\"private.owned_ai_retirement_guard()\",\"sha256\":\"8cbbd706652a3f41eb39db83da3a34757557950bd06364d4b5741fdcf86d7ff2\",\"resultType\":\"trigger\",\"language\":\"